#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <set>
#include <utility>
using namespace std;

int main(){
vector<double> observed={1,1.1,0.9,1.2,1,10};
vector<double> sorted=observed;
sort(sorted.begin(),sorted.end());
double median=(sorted[2]+sorted[3])/2;
vector<double> deviation;
for(double value:observed)deviation.push_back(fabs(value-median));
sort(deviation.begin(),deviation.end());
double mad=(deviation[2]+deviation[3])/2;
for(double value:observed)
    cout<<value<<" robust deviation "<<fabs(value-median)/(mad+1e-9)<<endl;
    return 0;
}

