#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <set>
#include <utility>
using namespace std;

int main(){
vector<double> first={1,2,1,2},second={3,4,3,4};
auto moments=[](const vector<double>& x){
    double m=0,v=0;
    for(double z:x)m+=z/x.size();
    for(double z:x)v+=pow(z-m,2)/x.size();
    return vector<double>{m,v};
};
vector<double> before=moments(first),after=moments(second);
cout<<"Mean shift "<<after[0]-before[0]
    <<" variance shift "<<after[1]-before[1]<<endl;
    return 0;
}

